package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.settings.ViewerPasses;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class PlanController {

    /**
     * A plan as the screen shows it, with how many claims it has made so far and its next five plan dates after the
     * sheet's today.
     */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, List<LocalDate> nextDates) {
        static PlanView of(Plan p, LocalDate today) {
            return new PlanView(p.getId(), p.getPersonId(), p.getAmount().toPlainString(), p.getStart(),
                    p.getEvery(), p.getDay(), p.getEnd(), p.getGenerated(), p.nextDates(today, 5));
        }
    }

    public record PlanForm(@NotNull BigDecimal amount, @NotNull LocalDate start, Integer every, Integer day,
            @NotNull LocalDate end) {
    }

    /** The claims a generate made, in the order made, and the sheet's plans as they stand. */
    public record GeneratedView(List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;
    private final SheetService sheets;

    public PlanController(PlanService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        LocalDate today = sheets.load(sheetId).getToday();
        return service.list(sheetId).stream().map(p -> PlanView.of(p, today)).toList();
    }

    @PostMapping("/people/{personId}/plans")
    public PlanView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @Valid @RequestBody PlanForm form,
            @SessionAttribute(SessionController.USER) String user) {
        Plan added = service.add(user, sheetId, personId, form.amount(), form.start(), form.every(), form.day(),
                form.end());
        return PlanView.of(added, sheets.load(sheetId).getToday());
    }

    /** Makes the plans' claims up to the sheet's today. */
    @ViewerPasses
    @PostMapping("/plans/generate")
    public GeneratedView generate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @SessionAttribute(SessionController.USER) String user) {
        PlanService.Generated g = service.generate(user, sheetId);
        LocalDate today = sheets.load(sheetId).getToday();
        return new GeneratedView(g.claims().stream().map(ClaimView::of).toList(),
                g.plans().stream().map(p -> PlanView.of(p, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * A person's plan: a draft claim of its amount on each plan date, from the start every so many days to the end, or
 * monthly on a day of the month. The plan dates a claim has been made on are kept, so each is made once.
 */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** The interval in days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for a plan every so many days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_claim", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date", nullable = false)
    private Set<LocalDate> made = new HashSet<>();

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    /**
     * The plan's dates from the start up to the last date: every so many days from the start, or the day of the month
     * in every month from the start's month (on the month's last day when it is shorter), those before the start left
     * out.
     */
    public List<LocalDate> datesUpTo(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(every)) {
                dates.add(on);
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate on = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!on.isBefore(start) && !on.isAfter(last)) {
                dates.add(on);
            }
        }
        return dates;
    }

    /** The first plan dates after the day and on or before the end, at most so many of them. */
    public List<LocalDate> nextDates(LocalDate after, int count) {
        return datesUpTo(end).stream().filter(on -> on.isAfter(after)).limit(count).toList();
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }

    /** Whether a claim has been made for the plan date. */
    public boolean hasMade(LocalDate date) {
        return made.contains(date);
    }

    public void markMade(LocalDate date) {
        made.add(date);
    }
}
package net.officefloor.hq.app.plan;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface PlanRepository extends JpaRepository<Plan, Long> {

    /** The sheet's plans in the order they were added. */
    List<Plan> findBySheetIdOrderByIdAsc(String sheetId);

    List<Plan> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);

    /** Moves the plans of one person to another. */
    @Modifying(flushAutomatically = true)
    @Query("update Plan p set p.personId = :into where p.sheetId = :sheetId and p.personId = :from")
    int movePlans(String sheetId, Long from, Long into);
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's plans. Generating makes, for each plan in the order they were added, a draft claim of its amount on
 * each of its plan dates up to its end and the sheet's today that has none yet, dated that day with an empty note, by
 * every rule of the claim form; a date the form refuses is skipped and tried again next time.
 */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final SettingsService settings;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;
    private final TransactionTemplate tx;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            SettingsService settings, Audit audit, PlatformTransactionManager transactions) {
        this.settings = settings;
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
        this.tx = new TransactionTemplate(transactions);
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /**
     * Adds a plan for the person, every so many days or monthly on a day of the month. Refused when the amount is
     * negative or has more than two decimals, both or neither of the interval and the day are given, the interval is
     * less than one day, the day is not 1 to 31, or the end is before the start.
     */
    @Transactional
    public Plan add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        if (amount == null || amount.signum() < 0 || amount.stripTrailingZeros().scale() > 2
                || amount.precision() - amount.scale() > 12) {
            throw refused("Enter an amount of at least 0 with up to two decimals.");
        }
        if ((every == null) == (day == null)) {
            throw refused("Enter either a number of days or a day of the month.");
        }
        if (every != null && every < 1) {
            throw refused("Enter a whole number of days of at least 1.");
        }
        if (day != null && (day < 1 || day > 31)) {
            throw refused("Enter a day of the month from 1 to 31.");
        }
        if (start == null || end == null) {
            throw refused("Enter a start date and an end date.");
        }
        if (end.isBefore(start)) {
            throw refused("The end date is before the start date.");
        }
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, scaled, start, every, day, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName() + " amount="
                + scaled.toPlainString() + " start=" + start + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
        return saved;
    }

    /** What a generate made: the claims, in the order they were made, and every plan of the sheet as it stands. */
    public record Generated(List<Claim> claims, List<Plan> plans) {
    }

    /**
     * Makes the plans' claims. Each claim is made in a change of its own, so one the claim form refuses changes
     * nothing and the others still go through. A user who may change nothing on the sheet makes none.
     */
    public Generated generate(String by, String sheetId) {
        if (settings.isReadOnly(sheetId, by)) {
            return new Generated(List.of(), list(sheetId));
        }
        LocalDate today = sheets.load(sheetId).getToday();
        List<Claim> made = new ArrayList<>();
        for (Plan plan : tx.execute(s -> plans.findBySheetIdOrderByIdAsc(sheetId))) {
            LocalDate last = plan.getEnd().isBefore(today) ? plan.getEnd() : today;
            for (LocalDate on : plan.datesUpTo(last)) {
                if (plan.hasMade(on)) {
                    continue;
                }
                LocalDate date = on;
                try {
                    made.add(tx.execute(s -> {
                        Plan current = plans.findById(plan.getId()).orElseThrow();
                        if (current.hasMade(date)) {
                            return null;
                        }
                        Claim claim = claims.add(by, sheetId, current.getPersonId(), current.getAmount(), date, "",
                                null, null, null);
                        current.markMade(date);
                        plans.saveAndFlush(current);
                        return claim;
                    }));
                } catch (ResponseStatusException refused) {
                    // the claim form refused this date: it is tried again next time
                }
            }
        }
        made.removeIf(c -> c == null);
        return new Generated(made, list(sheetId));
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, Injectable, computed, inject, input, signal } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from '../claims/claims';

export interface PlanView {
  id: number;
  personId: number;
  amount: string;
  start: string;
  // The interval in days, or null for a plan that runs monthly on `day`.
  every: number | null;
  day: number | null;
  end: string;
  // How many claims the plan has made so far.
  generated: number;
  // The first five plan dates after the sheet's today and on or before the end.
  nextDates: string[];
}

// The plans of the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PlanStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly list = signal<readonly PlanView[]>([]);

  /** Re-read the sheet's plans from the store. */
  async load(sheet: string): Promise<void> {
    this.list.set([]);
    const l = await firstValueFrom(this.http.get<PlanView[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`));
    if (this.session.sheetId() === sheet) this.list.set(l);
  }

  async add(sheet: string, personId: number, form: { amount: string; start: string; every: number | null; day: number | null; end: string }): Promise<void> {
    const p = await firstValueFrom(
      this.http.post<PlanView>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/plans`, form),
    );
    if (this.session.sheetId() === sheet) this.list.update((l) => [...l.filter((x) => x.id !== p.id), p]);
  }

  /** Makes the plans' claims up to the sheet's today: the claims made, in the order they were made. */
  async generate(sheet: string): Promise<Claim[]> {
    const g = await firstValueFrom(
      this.http.post<{ claims: Claim[]; plans: PlanView[] }>(`/api/sheets/${encodeURIComponent(sheet)}/plans/generate`, null),
    );
    if (this.session.sheetId() === sheet) this.list.set(g.plans);
    return g.claims;
  }
}

// A person's plans, and the form that adds one, every so many days or monthly on a day of the month. An amount the
// claim form would refuse without a claim to correct, both or neither of an interval and a day, an interval under one
// day, a day outside 1 to 31, or an end before the start is refused.
@Component({
  selector: 'app-person-plans',
  imports: [FigPipe],
  template: `
    <table>
      <caption class="visually-hidden">Plans of {{ personName() }}</caption>
      <thead>
        <tr>
          <th scope="col">Amount</th><th scope="col">Start</th><th scope="col">Every (days)</th>
          <th scope="col">Day of month</th><th scope="col">End</th><th scope="col">Claims made</th>
          <th scope="col">Next dates</th>
        </tr>
      </thead>
      <tbody>
        @for (pl of plans(); track pl.id) {
          <tr [attr.data-testid]="'plan-row-' + pl.id">
            <td data-testid="plan-figure">{{ pl.amount | fig }}</td>
            <td data-testid="plan-start">{{ pl.start | fig }}</td>
            <td data-testid="plan-every">{{ (pl.every ?? '') | fig }}</td>
            <td data-testid="plan-day">{{ (pl.day ?? '') | fig }}</td>
            <td data-testid="plan-end">{{ pl.end | fig }}</td>
            <td data-testid="plan-generated">{{ pl.generated | fig }}</td>
            <td data-testid="plan-next-dates">{{ (pl.nextDates.join(', ')) | fig }}</td>
          </tr>
        }
      </tbody>
    </table>
    <form (submit)="add($event)" [attr.aria-label]="'Add a plan for ' + personName()">
      <label [for]="'plan-amount-' + personId()">Plan amount</label>
      <input
        [id]="'plan-amount-' + personId()"
        data-testid="plan-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-start-' + personId()">Start</label>
      <input
        type="date"
        [id]="'plan-start-' + personId()"
        data-testid="plan-form-start"
        [value]="start()"
        (input)="start.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-every-' + personId()">Every (days)</label>
      <input
        [id]="'plan-every-' + personId()"
        data-testid="plan-form-every"
        inputmode="numeric"
        [value]="every()"
        (input)="every.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-day-' + personId()">Or monthly on day</label>
      <input
        [id]="'plan-day-' + personId()"
        data-testid="plan-form-day"
        inputmode="numeric"
        [value]="day()"
        (input)="day.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-end-' + personId()">End</label>
      <input
        type="date"
        [id]="'plan-end-' + personId()"
        data-testid="plan-form-end"
        [value]="end()"
        (input)="end.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="plan-form-submit">
        Add plan<span class="visually-hidden"> for {{ personName() }}</span>
      </button>
      @if (error(); as err) {
        <p role="alert" data-testid="plan-error">{{ err | fig }}</p>
      }
    </form>
  `,
})
export class PersonPlans {
  private readonly session = inject(Session);
  private readonly store = inject(PlanStore);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();

  protected readonly plans = computed(() => this.store.list().filter((p) => p.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly start = signal('');
  protected readonly every = signal('');
  protected readonly day = signal('');
  protected readonly end = signal('');
  protected readonly error = signal<string | null>(null);
  // A submit in flight: a second one before it answers is ignored.
  private submitting = false;

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const amount = this.amount().trim();
    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
      this.error.set('Enter an amount of at least 0 with up to two decimals.');
      return;
    }
    const every = this.every().trim();
    const day = this.day().trim();
    if (!every === !day) {
      this.error.set('Enter either a number of days or a day of the month.');
      return;
    }
    if (every && (!/^\d+$/.test(every) || Number(every) < 1)) {
      this.error.set('Enter a whole number of days of at least 1.');
      return;
    }
    if (day && (!/^\d+$/.test(day) || Number(day) < 1 || Number(day) > 31)) {
      this.error.set('Enter a day of the month from 1 to 31.');
      return;
    }
    // a blank start takes the sheet's today
    const start = this.start() || this.session.sheetToday() || '';
    const end = this.end();
    if (!start || !end) {
      this.error.set('Enter a start date and an end date.');
      return;
    }
    if (end < start) {
      this.error.set('The end date is before the start date.');
      return;
    }
    this.submitting = true;
    try {
      await this.store.add(sheet, this.personId(), {
        amount,
        start,
        every: every ? Number(every) : null,
        day: day ? Number(day) : null,
        end,
      });
    } catch (err) {
      const reason = err instanceof HttpErrorResponse ? (err.error as { message?: string } | null)?.message : null;
      this.error.set(
        err instanceof HttpErrorResponse && err.status === 403
          ? 'Your role may not add a plan on this sheet.'
          : reason || 'Could not add the plan.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
-- A person's plans: an amount, made a draft claim on each plan date from the start, every so many days, to the end.
-- Each plan date a claim was made on is kept once, so generating again makes none for it; a date the claim form
-- refused is not kept and is tried again the next time.
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL CHECK (every_days >= 1),
    end_date   DATE           NOT NULL,
    CHECK (end_date >= start_date)
);
CREATE INDEX plan_sheet ON plan (sheet_id, id);

CREATE TABLE plan_claim (
    plan_id BIGINT NOT NULL REFERENCES plan (id) ON DELETE CASCADE,
    on_date DATE   NOT NULL,
    PRIMARY KEY (plan_id, on_date)
